function shell(inner,active='Home'){if(learningLayer)closeLearningLayer();const channels=homeData?.channels||['For You','Composition 101','Academic English','Prof. Myrick','Critical Thinking','+'];app.innerHTML=`<div class="shell"><div class="top"><div class="brand">Learnly <span class="muted small">Prototype 0.6 · Stage 5B.1</span></div><div class="channels channelTiles">${channels.map(channelTile).join('')}</div></div><main class="content">${banner()}${inner}</main><nav class="nav">${['Home','Explore','Create','Saved','Profile'].map(n=>`<button class="${n===active?'active':''}" onclick="nav('${n}')"><span class="icon">${({Home:'⌂',Explore:'⌕',Create:'＋',Saved:'🔖',Profile:'○'})[n]}</span>${n}</button>`).join('')}</nav></div>`}
function accentClassFor(label=''){const x=String(label).toLowerCase();if(x.includes('composition')||x.includes('comp 101'))return'accent-writing';if(x.includes('academic english'))return'accent-language';if(x.includes('prof. myrick')||x.includes('prof myrick'))return'accent-person';if(x.includes('critical thinking'))return'accent-thinking';if(x.includes('for you'))return'accent-personal';return'accent-neutral'}
