function renderPanel(p){
  const d=p.panel_payload;
  const total=currentActivity?.stack?.panels?.length||5;
  const step=panelIndex+1;
  const isKey=String(d.heading||'').toLowerCase()==='key idea';
  let h=`<div class="panel ${isKey?'keyPanel':''}">`;
  h+=`<div class="panelHeader"><div class="contextPill">Composition 101</div><div class="panelProgress">Week 1</div></div>`;
  h+=`<div class="panelTitleBlock"><h1>${esc(d.heading||'')}</h1></div>`;
  if(d.quote)h+=`<div class="exampleBlock"><div class="exampleLabel">Example</div><div class="exampleText">${esc(d.quote)}</div></div>`;
  if(d.body){
    if(isKey) h+=`<div class="keyIdeaBox">${esc(d.body)}</div>`;
    else h+=`<div class="panelBody">${esc(d.body)}</div>`;
  }
  if(d.prompt)h+=`<div class="questionBlock"><div class="questionLabel">Your turn</div><h2 class="prompt">${esc(d.prompt)}</h2></div>`;
  if(d.options){
    const gridClass=d.options.length===4?' optionGrid':'';
    h+=`<div class="chips${gridClass}">${d.options.map(o=>`<button class="chip ${(selected[p.panel_id]||[]).includes(o)?'selected':''}" onclick="toggleOption('${p.panel_id}','${encodeURIComponent(o)}')">${esc(o)}</button>`).join('')}</div>`;
    const checked=panelChecks[p.panel_id];
    const attempts=panelAttempts[p.panel_id]||0;
    if(!checked||checked.dirty){
      h+=`<div class="panelCheckRow"><button class="btn secondary checkBtn" ${(selected[p.panel_id]||[]).length?'':'disabled'} onclick="checkPanel('${p.panel_id}')">${attempts?'Check Again':'Check'}</button></div>`;
    }else{
      h+=`<div class="panelFeedback ${checked.correct?'good':'developing'}"><div class="feedbackTitle">${checked.correct?'✓ Exactly.':checked.revealed?'Here’s the key idea.':'Almost.'}</div><div>${esc(checked.text)}</div>${checked.why?`<div class="whyFeedback">${esc(checked.why)}</div>`:''}${!checked.correct&&!checked.revealed?`<div class="feedbackHint">Adjust your choices above, then check again.</div>`:''}</div>`;
    }
  }
  return h+`</div>`;
}
async function persistPanel(p,response){const state={panelIndex,selected,panelChecks,panelAttempts,current_panel_id:p.panel_id,updated_at:new Date().toISOString()};await localDB.set('panelState:'+currentActivity.activity_instance_id,state);currentActivity.stack.progress={current_panel_id:p.panel_id,panels_viewed:[...(currentActivity.stack.progress?.panels_viewed||[])],panel_responses:selected};await localDB.set('currentActivity',currentActivity);return sendOrQueue(`/api/activities/${currentActivity.activity_instance_id}/panel`,{panel_id:p.panel_id,response})}
async function showStack(){const ps=currentActivity.stack.panels;if(activityHydratedFor!==currentActivity.activity_instance_id){const local=await localDB.get('panelState:'+currentActivity.activity_instance_id),pr=local||currentActivity.stack.progress;if(pr?.current_panel_id){const i=ps.findIndex(p=>p.panel_id===pr.current_panel_id);if(i>=0)panelIndex=i;selected=pr.selected||pr.panel_responses||{};panelChecks=pr.panelChecks||{};panelAttempts=pr.panelAttempts||{}}else{panelIndex=0;selected={};panelChecks={};panelAttempts={}}activityHydratedFor=currentActivity.activity_instance_id}const p=ps[panelIndex];await persistPanel(p,selected[p.panel_id]);const dots=ps.map((_,i)=>`<button class="dot ${i===panelIndex?'active':''}" aria-label="Go to panel ${i+1}" onclick="goToPanel(${i})"></button>`).join('');const support=panelIndex===ps.length-1?`<div class="completionActionStack"><button class="supportChoice" onclick="startSupport('help')">I Need More Help</button><button class="btn primary" onclick="completeActivity()">Got It</button></div>`:'';const requiresCheck=!!p.panel_payload?.options;const chk=panelChecks[p.panel_id];const canAdvance=!requiresCheck||!!(chk&&(chk.correct||chk.revealed));const stackSize=(requiresCheck||p.panel_payload?.quote)?'stackSize-large':'stackSize-standard';shell(`<div class="card cardAccent accent-writing stack ${stackSize}">${renderPanel(p)}${support}<div class="dots">${dots}</div><div class="stacknav"><button class="btn ghost" ${panelIndex===0?'disabled':''} onclick="move(-1)">←</button><span class="status">${panelIndex+1} of ${ps.length}</span>${panelIndex===ps.length-1?`<span aria-hidden="true"></span>`:`<button class="btn ghost" ${canAdvance?'':'disabled'} onclick="move(1)">→</button>`}</div></div>`)}
async function toggleOption(pid,encoded){const opt=decodeURIComponent(encoded);let arr=selected[pid]||[];arr=arr.includes(opt)?arr.filter(x=>x!==opt):[...arr,opt];selected[pid]=arr;if(panelChecks[pid]&&!panelChecks[pid].correct){panelChecks[pid]={...panelChecks[pid],dirty:true}}await persistPanel(currentActivity.stack.panels.find(p=>p.panel_id===pid),arr);showActivity()}
async function checkPanel(pid){const p=currentActivity.stack.panels.find(x=>x.panel_id===pid);if(!p)return;const d=p.panel_payload||{};const chosen=selected[pid]||[];const correct=d.correct_options||[];const ok=chosen.length===correct.length&&correct.every(x=>chosen.includes(x));const attempt=(panelAttempts[pid]||0)+1;panelAttempts[pid]=attempt;let text='',revealed=false;if(ok){text=d.feedback_correct||'Exactly.'}else if(attempt===1){text=d.feedback_hint1||'Almost. One or more choices need another look. Think about how the message sounds, how much detail it gives, and what it assumes the reader already knows.'}else if(attempt===2){text=d.feedback_hint2||'Still close. Focus on tone, wording or length/detail, and what the reader is expected to already understand.'}else{text=d.feedback_partial||'Here are the key features to notice.';revealed=true}panelChecks[pid]={correct:ok,revealed,dirty:false,text,why:(ok||revealed)?(d.why_feedback||''):''};await persistPanel(p,chosen);await sendOrQueue(`/api/activities/${currentActivity.activity_instance_id}/panel`,{panel_id:pid,response:chosen,checked:true,correct:ok,attempt,revealed});showActivity()}function move(d){panelIndex=Math.max(0,Math.min(currentActivity.stack.panels.length-1,panelIndex+d));return showActivityFromTop()}function goToPanel(i){panelIndex=Math.max(0,Math.min(currentActivity.stack.panels.length-1,i));return showActivityFromTop()}
async function showQuickCheck(){const qc=currentActivity.quick_check,att=qc.attempt;if(att.attempt_state==='offered')return shell(`<div class="card cardAccent accent-writing quickCheckCard">${courseHeader()}<div class="activityLabel">Quick Check</div><h1>Check Your Understanding?</h1><div class="effort">About 1 min</div><div class="actions"><button class="btn primary" onclick="qcDecision('accept')">Yes</button><button class="btn ghost" onclick="qcDecision('decline')">Not Now</button></div></div>`);const responses=qc.responses||[],answered=new Set(responses.map(r=>r.question_id));if(qFeedback){const f=qFeedback;const help=!f.correct&&!f.queued?`<div class="supportActions"><button class="supportChoice" onclick="startSupport('help')">I Need More Help</button></div>`:'';return shell(`<div class="card cardAccent accent-writing quickCheckCard">${courseHeader()}<div class="activityLabel">Quick Check Feedback</div><h1>${f.correct?'✓ Yes':'Not Quite Yet'}</h1><div class="muted bodycopy">${esc(f.feedback)}</div>${help}<div class="actions"><button class="btn primary" onclick="afterFeedback()">${f.completed?'Continue':'Next'}</button></div></div>`)}let idx=qc.questions.findIndex(q=>!answered.has(q.question_id));if(idx<0)idx=qc.questions.length-1;qIndex=idx;const q=qc.questions[qIndex],stim=q.stimulus_payload;let s='';if(stim?.messages)s=stim.messages.map(m=>`<div class="quote"><strong>${esc(m.label)}</strong><br>${esc(m.text)}</div>`).join('');shell(`<div class="card cardAccent accent-writing quickCheckCard">${courseHeader()}<div class="activityLabel">Quick Check · ${qIndex+1} of ${qc.questions.length}</div><h1>${esc(q.prompt)}</h1>${s}<div class="choicegrid">${q.response_options.map(o=>`<button class="choice" onclick="submitQC('${q.question_id}','${encodeURIComponent(o)}')">${esc(o)}</button>`).join('')}</div></div>`)}
async function qcDecision(a){const r=await api(`/api/quick-checks/${currentActivity.activity_instance_id}/${a}`,{method:'POST',body:'{}'});if(a==='decline')return loadNext(r.next_activity_instance_id);currentActivity=await api('/api/activities/'+currentActivity.activity_instance_id);showActivityFromTop()}
async function submitQC(qid,enc){const response=decodeURIComponent(enc),r=await sendOrQueue(`/api/quick-checks/${currentActivity.activity_instance_id}/responses`,{question_id:qid,response,started_at:new Date().toISOString()});if(r.queued){qFeedback={correct:null,feedback:'Your answer is saved on this device. Feedback will be available after you reconnect.',completed:false,queued:true};return showActivityFromTop()}qFeedback=r;showActivityFromTop()}
async function afterFeedback(){const f=qFeedback;qFeedback=null;if(f.queued)return loadHome();if(f.completed)return loadNext(f.next_activity_instance_id);currentActivity=await api('/api/activities/'+currentActivity.activity_instance_id);showActivityFromTop()}

// A native modal keeps the original card mounted and makes the background inert.
let learningLayer=null,layerGeneration=0;
const layerQuestions=new Map();
function closeLearningLayer(){
  layerGeneration++;
  if(!learningLayer)return;
  const {dialog,focus,scrollX,scrollY,bodyStyle}=learningLayer;
  learningLayer=null;
  dialog.close();dialog.remove();
  document.body.style.cssText=bodyStyle;
  window.scrollTo(scrollX,scrollY);
  if(focus?.isConnected)focus.focus({preventScroll:true});
  supportState=null;supportOrigin=null;
}
function showLearningLayer(inner,kind='support'){
  if(!learningLayer){
    const dialog=document.createElement('dialog');
    dialog.className='learningSheet';dialog.setAttribute('aria-label',kind==='reading'?'Why This Matters':'Learning support');
    learningLayer={dialog,kind,supportPathId:crypto.randomUUID(),focus:document.activeElement,scrollX:window.scrollX,scrollY:window.scrollY,bodyStyle:document.body.style.cssText};
    document.body.append(dialog);
    document.body.style.position='fixed';document.body.style.top=`-${learningLayer.scrollY}px`;document.body.style.width='100%';
    dialog.addEventListener('cancel',e=>{e.preventDefault();closeLearningLayer()});
    dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeLearningLayer()}});
    dialog.showModal();
  }
  const dialog=learningLayer.dialog;
  dialog.innerHTML=`<div class="sheetChrome"><span class="sheetHandle" aria-hidden="true"></span><button class="btn ghost sheetClose" aria-label="Close learning support" onclick="closeLearningLayer()">✕</button></div><div class="sheetContent">${inner}${askAboutHTML()}</div>`;
  dialog.scrollTop=0;
  dialog.querySelector('.sheetClose').focus({preventScroll:true});
}
function layerContext(){
  return learningLayer?.kind==='reading'?String(currentActivity.content.body||''):String(supportState?.current_unit?.content_payload?.body||'Think about giving directions. Someone who knows the campus needs less detail than someone visiting for the first time. The information changes because the audience needs different support.');
}
function layerQuestionKey(){return currentActivity.activity_instance_id+':'+learningLayer.kind+':'+(supportState?.current_unit?.support_unit_id||'overview')}
function askAboutHTML(){
  const saved=layerQuestions.get(layerQuestionKey())||{question:'',answer:''};
  return `<form class="askAbout" onsubmit="askAboutThis(event)"><label for="contextQuestion">Ask About This</label><p class="muted small" id="askHint">Explore this ${learningLayer.kind==='reading'?'reading':'explanation'} with a passage to consider. Available offline.</p><textarea id="contextQuestion" rows="2" maxlength="600" required aria-describedby="askHint" placeholder="What would you like to understand?" oninput="rememberLayerQuestion(this.value)">${esc(saved.question)}</textarea><div class="actions"><button class="btn secondary" type="submit">Ask About This</button></div><div class="contextAnswer" id="contextAnswer" role="status">${esc(saved.answer)}</div></form>`;
}
function rememberLayerQuestion(question){const key=layerQuestionKey(),saved=layerQuestions.get(key)||{};layerQuestions.set(key,{...saved,question})}
function askAboutThis(event){
  event.preventDefault();
  const question=document.getElementById('contextQuestion').value.trim();if(!question)return;
  const words=question.toLowerCase().match(/[a-z]{4,}/g)||[];
  const sentences=layerContext().match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[];
  const ranked=sentences.map(text=>({text:text.trim(),score:words.filter(w=>!['this','that','what','does','about','would','could','should','explain','reading','help'].includes(w)&&text.toLowerCase().includes(w)).length})).sort((a,b)=>b.score-a.score);
  const excerpt=ranked[0]?.text||layerContext();
  const answer=`${ranked[0]?.score?'A related passage to consider':'A starting point in this '+(learningLayer.kind==='reading'?'reading':'explanation')}: “${excerpt}”\n\n${learningLayer.kind==='reading'?'What claim is being made, and what reason supports it? Use that connection when forming your own reading response.':'How would you explain the same idea to a friend and to an instructor? Notice what changes in tone, context, and detail.'}`;
  void logHelp('contextual_question_submitted','contextual_question',{question,answer});
  layerQuestions.set(layerQuestionKey(),{question,answer});document.getElementById('contextAnswer').textContent=answer;
}
function showWhyThisMatters(){
  showLearningLayer(`<div class="card cardAccent accent-writing"><div class="contextPill">Reading support</div><h1>Why This Matters</h1><p class="bodycopy">This reading gives you a claim to examine before writing your own response. Notice how the writer supports an idea, consider the needs of different learners, and decide which reasons you find convincing. You’ll use these choices to explain your own position clearly to a university audience.</p></div>`,'reading');
}
function supportLayer(inner){showLearningLayer(inner,'support')}

const helpChoices={
  alternative_explanation:{title:'Explain It Another Way',body:'Think about giving directions. Someone who knows the campus needs less detail than someone visiting for the first time. The information changes because the audience needs different support.',provenance:'AI_generated_grounded_prototype'},
  worked_example:{title:'Show Me an Example',body:'To a friend: “Can you send me the notes? I missed class.” To an instructor: “Dear Professor, I missed Tuesday’s class. Could you let me know where to find the notes? Thank you.” Both messages request notes. The second gives more context and uses a more formal tone to suit its audience.',provenance:'authored_prototype'},
  comprehension_check:{title:'Check My Understanding',body:'You are asking an instructor for an assignment extension. Which approach best suits this audience?',provenance:'authored_prototype'},
  external_resource:{title:'Find Another Resource',body:'Purdue OWL’s Elements of Rhetorical Situations explores how audience, purpose, writer, text, and setting shape communication. As you read, notice which details a reader needs and why.',provenance:'curated_external_resource'}
};
function logHelp(event,supportType=null,details={}){
  return sendOrQueue('/api/support/events',{event,event_id:crypto.randomUUID(),support_path_id:learningLayer?.supportPathId,support_unit_id:supportState?.current_unit?.instance_id,content: supportState?.current_unit?.content_payload,activity_instance_id:currentActivity.activity_instance_id,support_type:supportType,provenance_type:supportType==='contextual_question'?'local_excerpt_rule':helpChoices[supportType]?.provenance||null,layer:learningLayer?.kind||'support',panel_index:panelIndex,...details});
}
function startSupport(){
  if(!currentActivity)return;
  supportState=null;
  supportLayer(`<div class="card supportCard"><h1>What would help most?</h1><div class="choicegrid">${Object.entries(helpChoices).map(([type,c])=>`<button class="choice" onclick="chooseHelp('${type}')">${esc(c.title)}</button>`).join('')}</div></div>`);
  void logHelp('support_hub_opened');
}
function chooseHelp(type){
  const c=helpChoices[type];if(!c)return;
  supportState={current_unit:{support_unit_id:type,instance_id:crypto.randomUUID(),content_payload:c}};
  supportLayer(`<div class="card supportCard"><h1>${esc(c.title)}</h1><p class="bodycopy">${esc(c.body)}</p>${type==='comprehension_check'?`<div class="choicegrid"><button class="choice" onclick="checkHelp(false)">Send a brief message with no assignment details</button><button class="choice" onclick="checkHelp(true)">Give clear context and make a respectful request</button></div><p id="helpCheckFeedback" role="status"></p>`:''}${type==='external_resource'?`<p><a class="btn secondary resourceLink" href="https://owl.purdue.edu/owl/general_writing/academic_writing/rhetorical_situation/elements_of_rhetorical_situations.html" target="_blank" rel="noopener noreferrer" onclick="logHelp('external_resource_opened','external_resource')">Read on Purdue OWL ↗</a></p><p class="muted small">The linked page requires a connection. The summary above is available offline.</p>`:''}<div class="actions"><button class="btn secondary" onclick="startSupport()">Other help options</button><button class="btn primary" onclick="finishHelp()">Got It</button></div></div>`);
  void logHelp('support_unit_presented',type);
}
function checkHelp(correct){document.getElementById('helpCheckFeedback').textContent=correct?'✓ Exactly. Clear context and a respectful request help the instructor understand what you need.':'Not quite yet. Think about the details your instructor needs and the tone that fits your request. Try again.';void logHelp('understanding_check_response','comprehension_check',{correct})}
function finishHelp(){void logHelp('support_resolved',supportState?.current_unit?.support_unit_id);closeLearningLayer()}
function returnFromSupport(){closeLearningLayer()}

async function showReading(){await sendOrQueue(`/api/activities/${currentActivity.activity_instance_id}/reading-start`,{});const c=currentActivity.content;const paras=String(c.body||'').split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('');shell(`<div class="card cardAccent accent-writing reading">${courseHeader()}<div class="activityLabel">${esc((c.source_label?.replace('Composition 101 · ','')||'Reading').replace('Week 1 · ',''))}</div><h1>${esc(c.title)}</h1><div class="effort">About ${esc(c.estimated_minutes||3)} min</div><div class="readingtext">${paras}</div><div class="actions whyMattersActions"><button class="btn secondary" onclick="showWhyThisMatters()">Why This Matters</button></div><div class="actions bookmarkActions"><button class="btn primary" onclick="completeActivity()">I've Read It</button>${bookmarkControl(currentActivity.saved,'toggleContentSave()')}</div></div>`)}
async function toggleContentSave(){if(currentActivity.saved){await api(`/api/saved/content/${currentActivity.content_version_id}`,{method:'DELETE'});currentActivity.saved=false}else{await sendOrQueue('/api/saved',{target_type:'content',target_id:currentActivity.content_version_id,offline_available:true});currentActivity.saved=true}await localDB.set('currentActivity',currentActivity);showActivity()}
async function writingChanged(v){writingText=v;await localDB.set('writingText:'+currentActivity.activity_instance_id,v);const el=document.getElementById('wordCount');if(el)el.textContent=`${String(v).trim()?String(v).trim().split(/\s+/).length:0} words`}
function speechSupported(){return !!(window.SpeechRecognition||window.webkitSpeechRecognition)}
function setVoiceStatus(msg=''){const el=document.getElementById('voiceStatus');if(el)el.textContent=msg}
function updateWritingBox(){const el=document.getElementById('writingBox');if(el){el.value=writingText;const wc=document.getElementById('wordCount');if(wc)wc.textContent=`${String(writingText).trim()?String(writingText).trim().split(/\s+/).length:0} words`}}
function updateReflectionBox(id){const el=document.getElementById('reflection-'+id);if(el)el.value=reflectionState.responses?.[id]||''}
function stopDictation(){if(activeRecognition){try{activeRecognition.stop()}catch{}activeRecognition=null}setVoiceStatus('')}
function startDictation(targetType,targetId=''){
  if(!speechSupported())return setVoiceStatus('Voice-to-text is not available in this browser. Try Chrome on a supported device.');
  stopDictation();
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition,rec=new SR();activeRecognition=rec;voiceTarget={targetType,targetId};rec.lang='en-US';rec.interimResults=true;rec.continuous=false;
  const activityId=currentActivity.activity_instance_id;
  const existing=targetType==='writing'?writingText:(reflectionState.responses?.[targetId]||'');let finalAdded='';
  setVoiceStatus('Listening… Speak naturally, then review the text before submitting.');
  rec.onresult=async e=>{if(currentActivity?.activity_instance_id!==activityId)return;let interim='',final='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)final+=t;else interim+=t}if(final)finalAdded+=(finalAdded?' ':'')+final.trim();const combined=[existing,finalAdded,interim].filter(Boolean).join(existing&&finalAdded?' ':'').replace(/\s+/g,' ').trim();if(targetType==='writing'){writingVoiceUsed=true;writingText=combined;await localDB.set('writingText:'+activityId,writingText);await localDB.set('writingVoiceUsed:'+activityId,true);updateWritingBox()}else{reflectionState.responses=reflectionState.responses||{};reflectionState.responseModes=reflectionState.responseModes||{};reflectionState.responses[targetId]=combined;reflectionState.responseModes[targetId]='speech_to_text';await localDB.set('reflection:'+activityId,reflectionState);updateReflectionBox(targetId)}};
  rec.onerror=e=>{setVoiceStatus(e.error==='not-allowed'?'Microphone access was not allowed. You can keep typing instead.':'Voice input stopped. You can try again or keep typing.')};
  rec.onend=()=>{activeRecognition=null;setVoiceStatus('Dictation finished. Review and edit the text before submitting.');};
  try{rec.start()}catch{setVoiceStatus('Voice input could not start. You can keep typing instead.')}
}

async function showWriting(){const c=currentActivity.content,w=currentActivity.writing||{};if(!writingText){const local=await localDB.get('writingText:'+currentActivity.activity_instance_id);writingText=local??w.latest_version?.text_content??''}if(!writingVoiceUsed)writingVoiceUsed=!!(await localDB.get('writingVoiceUsed:'+currentActivity.activity_instance_id));if(c.phase==='baseline'&&writingBaselineConfidence===null){writingBaselineConfidence=await localDB.get('baselineConfidence:'+currentActivity.activity_instance_id)||null}if(w.draft?.draft_status==='submitted'&&w.feedback?.length&&!writingFeedback)writingFeedback=w.feedback;if(writingFeedback&&c.feedback_mode!=='none'){const strength=writingFeedback.find(x=>x.feedback_category==='strength'),priority=writingFeedback.find(x=>x.feedback_category==='priority_improvement');return shell(`<div class="card cardAccent accent-writing feedbackCard">${courseHeader()}<div class="activityLabel">Writing Feedback</div><h1>Feedback on your reading response</h1><div class="feedbackPair"><div class="feedbackBlock"><div class="feedbackEyebrow">Strength</div><strong>What’s working</strong><p>${esc(strength?.feedback_text||'You established a clear starting point.')}</p></div><div class="feedbackBlock"><div class="feedbackEyebrow">Next step</div><strong>One thing to strengthen</strong><p>${esc(priority?.feedback_text||'Add more explanation for your reader.')}</p></div></div><div class="actions bookmarkActions"><button class="btn primary" onclick="continueAfterWriting()">Continue</button>${bookmarkControl((currentActivity.writing?.feedback?.[0]||writingFeedback?.[0])?.saved,'saveWritingFeedback()')}</div></div>`)}const isBaseline=c.phase==='baseline';const confidence=isBaseline&&c.self_assessment?`<div class="baselineCheck"><div class="fieldPrompt">${esc(c.self_assessment.text)}</div><div class="choicegrid compactChoices">${c.self_assessment.options.map(o=>`<button class="choice ${writingBaselineConfidence===o?'selectedChoice':''}" onclick="setBaselineConfidence('${encodeURIComponent(o)}')">${esc(o)}</button>`).join('')}</div></div>`:'';shell(`<div class="card cardAccent accent-writing writingCard">${courseHeader()}<div class="activityLabel">${isBaseline?'Starting Point':'Reading Response'}</div><h1>${esc(c.title)}</h1>${confidence}<div class="writingPrompt"><div class="promptText">${esc(c.prompt)}</div><div class="taskInstruction">${esc(c.target_words)} ${esc(c.note)}</div></div><textarea id="writingBox" class="writingBox" placeholder="Write your response here." oninput="writingChanged(this.value)">${esc(writingText)}</textarea><div class="writingMeta"><span id="wordCount">${String(writingText).trim()?String(writingText).trim().split(/\s+/).length:0} words</span><span>Autosaved on this device</span></div><div class="speechControlRow"><button class="btn modeBtn speechBtn" onclick="startDictation('writing')" ${speechSupported()?'':'disabled'}>🎙 Speak</button></div><div id="voiceStatus" class="voiceStatus">${speechSupported()?'':'Voice-to-text is unavailable in this browser.'}</div><div class="actions writingActions"><button class="btn ghost" onclick="saveDraft()">Save Draft</button><button class="btn primary" onclick="submitWriting()">Submit</button></div></div>`) }
async function setBaselineConfidence(enc){writingBaselineConfidence=decodeURIComponent(enc);await localDB.set('baselineConfidence:'+currentActivity.activity_instance_id,writingBaselineConfidence);showActivity()}
async function saveDraft(){const r=await sendOrQueue(`/api/writing/${currentActivity.activity_instance_id}/save`,{text:writingText,source_mode:writingVoiceUsed?'speech_to_text':'typed'});shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Writing</div><h1>${r.queued?'Saved on this device':'Draft saved ✓'}</h1><div class="muted">${r.queued?'Your draft will sync when you reconnect.':'You can keep editing whenever you are ready.'}</div><div class="actions"><button class="btn primary" onclick="showActivityFromTop()">Keep Writing</button></div></div>`)}
async function submitWriting(){const c=currentActivity.content;if(c.phase==='baseline'&&!writingBaselineConfidence)return shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Starting point</div><h1>Choose your comfort level first</h1><div class="muted">Select the option that best describes how comfortable you currently feel with university writing.</div><div class="actions"><button class="btn primary" onclick="showActivityFromTop()">Back</button></div></div>`);if(!String(writingText).trim())return shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Writing</div><h1>Add your response first</h1><div class="muted">There needs to be something to submit.</div><div class="actions"><button class="btn primary" onclick="showActivityFromTop()">Back to Writing</button></div></div>`);const r=await sendOrQueue(`/api/writing/${currentActivity.activity_instance_id}/submit`,{text:writingText,source_mode:writingVoiceUsed?'speech_to_text':'typed',baseline_confidence:writingBaselineConfidence});if(r.queued)return shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Writing</div><h1>Saved on this device ✓</h1><div class="muted">Your writing will sync when you reconnect.</div><div class="actions"><button class="btn primary" onclick="loadHome()">Home</button></div></div>`);if(c.feedback_mode==='none'){return continueAfterWriting()}writingFeedback=r.feedback;currentActivity=await api('/api/activities/'+currentActivity.activity_instance_id);showActivityFromTop()}
async function continueAfterWriting(){const r=await api(`/api/writing/${currentActivity.activity_instance_id}/continue`,{method:'POST',body:'{}'});return loadNext(r.next_activity_instance_id)}
async function saveWritingFeedback(){const fb=currentActivity.writing?.feedback?.[0]||writingFeedback?.[0];if(fb){if(fb.saved)await sendOrQueue('/api/saved/feedback/'+fb.feedback_id,undefined,'DELETE');else await sendOrQueue('/api/saved',{target_type:'feedback',target_id:fb.feedback_id,offline_available:true});fb.saved=!fb.saved;for(const x of writingFeedback||[])if(x.feedback_id===fb.feedback_id)x.saved=fb.saved;await localDB.set('currentActivity',currentActivity)}return showActivity()}
async function showReflection(){const c=currentActivity.content;if(!reflectionState.responses||Object.keys(reflectionState.responses).length===0){const local=await localDB.get('reflection:'+currentActivity.activity_instance_id);if(local)reflectionState=local}reflectionState.responseModes=reflectionState.responseModes||{};const prompts=c.prompts||[];shell(`<div class="card cardAccent accent-writing reflectionCard">${courseHeader()}<div class="activityLabel">Reflection</div><h1>${esc(c.title)}</h1>${prompts.map((p,i)=>`<div class="reflectionPrompt"><div class="promptText">${esc(p.text)}</div><textarea id="reflection-${p.id}" class="shortBox" placeholder="Write your response here." oninput="reflectionChanged('${p.id}',this.value)">${esc(reflectionState.responses?.[p.id]||'')}</textarea><div class="reflectionInputTools speechControlRow"><button class="btn modeBtn speechBtn" onclick="startDictation('reflection','${p.id}')" ${speechSupported()?'':'disabled'}>🎙 Speak</button></div></div>`).join('')}<div class="confidenceBlock"><div class="questionLabel">Confidence</div><div class="promptText">${esc(c.confidence.text)}</div><div class="choicegrid compactChoices">${c.confidence.options.map(o=>`<button class="choice ${reflectionState.confidence===o?'selectedChoice':''}" onclick="setConfidence('${encodeURIComponent(o)}')">${esc(o)}</button>`).join('')}</div></div><div class="actions reflectionActions"><button class="btn primary" onclick="submitReflection()">Finish Reflection</button></div></div>`)}
async function reflectionChanged(id,v){reflectionState.responses=reflectionState.responses||{};reflectionState.responseModes=reflectionState.responseModes||{};reflectionState.responses[id]=v;if(!reflectionState.responseModes[id])reflectionState.responseModes[id]='text';await localDB.set('reflection:'+currentActivity.activity_instance_id,reflectionState)}
async function setConfidence(enc){reflectionState.confidence=decodeURIComponent(enc);await localDB.set('reflection:'+currentActivity.activity_instance_id,reflectionState);showActivity()}
async function submitReflection(){const c=currentActivity.content,missing=(c.prompts||[]).some(p=>!String(reflectionState.responses?.[p.id]||'').trim());if(missing||!reflectionState.confidence)return shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Reflection</div><h1>One more step</h1><div class="muted">Please answer both short prompts and choose a confidence level.</div><div class="actions"><button class="btn primary" onclick="showActivityFromTop()">Back</button></div></div>`);const r=await sendOrQueue(`/api/reflections/${currentActivity.activity_instance_id}/submit`,reflectionState);if(r.queued)return shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Reflection</div><h1>Saved on this device ✓</h1><div class="muted">Your reflection will sync when you reconnect.</div><div class="actions"><button class="btn primary" onclick="loadHome()">Home</button></div></div>`);return loadNext(r.next_activity_instance_id)}
function showCompletion(){const c=currentActivity.content;shell(`<div class="card cardAccent accent-writing completionCard"><div class="successMark">✓</div><div class="contextPill">Composition 101</div><h1>${esc(c.title)}</h1><div class="muted">${esc(c.subtitle)}</div><div class="completionSectionLabel">This week you worked on</div><div class="summaryChips completionGrid">${(c.summary||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="actions completionActions"><button class="btn primary" onclick="finishWeek('done')">Done for Now</button><button class="btn ghost" onclick="finishWeek('explore')">Keep Exploring</button></div></div>`)}
