async function showWeekSummary(){const d=await api('/api/me/learning');shellFromTop(`<div class="card cardAccent accent-writing weekSummaryCard">${courseHeader('Week 1')}<h1>Writing for Different Audiences</h1><div class="completionStatus compactStatus"><span class="completionCheck">✓</span><span>Completed</span></div><div class="muted">Your Week 1 work is complete. Review any part without changing your completion status.</div><div class="summaryChips"><span>Starting-Point Writing</span><span>Audience</span><span>Purpose</span><span>Critical Reading</span><span>Reading Response</span></div>${d.writing?`<div class="listrow"><strong>Writing submitted</strong><span>${d.writing.word_count||0} ${(d.writing.word_count||0)===1?'word':'words'}</span></div>`:''}<div class="reviewActions"><button class="btn primary" onclick="openWeekReview()">Review Week 1</button><button class="btn ghost" onclick="loadHome()">Back Home</button></div></div>`)}
async function openWeekReview(){const d=await api('/api/review/week1');window.__weekReview=d;const labels={learning_stack:'Audience learning stack',quick_check:'Quick Check',reading:'Course reading',writing:'Writing & feedback',reflection:'Reflection'};shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Composition 101</div><h1>Review Week 1</h1><div class="muted">Choose any completed activity to revisit. Review does not alter your completed status.</div><div class="reviewList">${d.activities.map((x,i)=>`<button class="reviewItem" onclick="openReviewItem(${i})"><strong>${esc(labels[x.type]||x.title)}</strong><span>${esc(x.title)}</span></button>`).join('')}</div><div class="actions"><button class="btn ghost" onclick="showWeekSummary()">Back</button></div></div>`)}
function reviewNav(i,total){return `<div class="reviewNav"><button class="btn ghost reviewStep" ${i<=0?'disabled':''} onclick="openReviewItem(${i-1})">← Previous</button><span class="muted small reviewCount">${i+1} of ${total}</span><button class="btn ghost reviewStep" ${i>=total-1?'disabled':''} onclick="openReviewItem(${i+1})">Next →</button></div>`}
function openReviewItem(i){const d=window.__weekReview;if(!d||!d.activities[i])return openWeekReview();const x=d.activities[i],p=x.payload,total=d.activities.length;let body='';if(x.type==='learning_stack'){body=`<div class="reviewPanels">${p.stack.panels.map((pn,idx)=>{const z=pn.panel_payload;return `<div class="reviewPanel"><div class="kicker">Panel ${idx+1}</div><h2>${esc(z.heading||'')}</h2>${z.quote?`<div class="quote">${esc(z.quote)}</div>`:''}${z.body?`<div class="muted bodycopy">${esc(z.body)}</div>`:''}${z.prompt?`<div class="prompt">${esc(z.prompt)}</div>`:''}${z.correct_options?`<div class="reviewAnswer"><strong>Key ideas</strong><div class="reviewKeyGrid">${z.correct_options.map(o=>`<span class="chip selected">${esc(o)}</span>`).join('')}</div></div>`:''}</div>`}).join('')}</div>`}
else if(x.type==='quick_check'){const q=p.quick_check;body=q.questions.map(qi=>{const r=(q.responses||[]).find(rr=>rr.question_id===qi.question_id);return `<div class="reviewPanel"><h2>${esc(qi.prompt)}</h2>${qi.stimulus_payload?.messages?qi.stimulus_payload.messages.map(m=>`<div class="quote"><strong>${esc(m.label)}</strong><br>${esc(m.text)}</div>`).join(''):''}<div class="listrow"><strong>Your answer</strong><span>${esc(r?.response_value||'Not answered')}</span></div>${r?`<div class="panelFeedback ${r.correctness?'good':'developing'}"><strong>${r.correctness?'✓ Correct':'Review this'}</strong><div>${esc(r.correctness?qi.feedback_correct:qi.feedback_incorrect)}</div></div>`:''}</div>`}).join('')}
else if(x.type==='reading'){const c=p.content;body=`<div class="readingtext">${String(c.body||'').split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}</div>`}
else if(x.type==='writing'){const w=p.writing||{},v=w.latest_version;body=`<div class="reviewPanel"><h2>Your submitted writing</h2><div class="quote">${esc(v?.text_content||'No submitted writing found.')}</div>${(w.feedback||[]).map(f=>`<div class="feedbackBlock ${f.feedback_category==='strength'?'good':''}"><strong>${esc(f.feedback_category==='strength'?"What's working":'Feedback')}</strong><p>${esc(f.feedback_text)}</p></div>`).join('')}</div>`}
else if(x.type==='reflection'){const rs=p.reflection?.responses||[];body=`<div class="reviewPanel"><h2>Your reflection</h2>${rs.map(r=>`<div class="listrow"><strong>${esc(r.prompt_id.replaceAll('_',' '))}</strong><span>${esc(r.response_text||r.confidence_level||'')}</span></div>`).join('')}</div>`}
shellFromTop(`<div class="card cardAccent accent-writing"><div class="contextPill">Composition 101</div><h1>${esc(x.title)}</h1>${body}${reviewNav(i,total)}<div class="reviewActions"><button class="btn secondary" onclick="openWeekReview()">Review Menu</button><button class="btn ghost" onclick="loadHome()">Home</button></div></div>`)}
