async function showResearch(){const d=await api('/api/research/events');shellFromTop(`<div class="card cardAccent accent-neutral"><div class="contextPill">Research Instrumentation</div><h1>Meaningful event stream</h1><div class="muted">This readable view confirms that the full Week 1 journey can be reconstructed without exposing raw JSON.</div><div class="timeline">${d.events.slice(-45).map(e=>`<div class="event"><span class="seq">${e.sequence_number}</span><div><strong>${esc(e.event_name.replaceAll('_',' '))}</strong><div class="muted small">${new Date(e.timestamp_utc_original).toLocaleString()}</div></div></div>`).join('')}</div><div class="actions"><button class="btn primary" onclick="loadHome()">Back Home</button></div></div>`)}
window.startSupport=startSupport;window.toggleCardSave=toggleCardSave;window.setBaselineConfidence=setBaselineConfidence;window.returnFromSupport=returnFromSupport;window.startDictation=startDictation;window.stopDictation=stopDictation;window.startOrContinue=startOrContinue;window.toggleOption=toggleOption;window.checkPanel=checkPanel;window.move=move;window.goToPanel=goToPanel;window.completeActivity=completeActivity;window.nav=nav;window.selectChannel=selectChannel;window.toggleWeekSave=toggleWeekSave;window.toggleContentSave=toggleContentSave;window.qcDecision=qcDecision;window.submitQC=submitQC;window.afterFeedback=afterFeedback;window.showFaculty=showFaculty;window.showResearch=showResearch;window.openMini=openMini;window.writingChanged=writingChanged;window.saveDraft=saveDraft;window.submitWriting=submitWriting;window.continueAfterWriting=continueAfterWriting;window.saveWritingFeedback=saveWritingFeedback;window.reflectionChanged=reflectionChanged;window.setConfidence=setConfidence;window.submitReflection=submitReflection;window.finishWeek=finishWeek;window.showWeekSummary=showWeekSummary;window.openWeekReview=openWeekReview;window.openReviewItem=openReviewItem;
window.addEventListener('keydown',e=>{if(learningLayer||!currentActivity||currentActivity.activity_type!=='learning_stack')return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});
window.addEventListener('online',async()=>{await localDB.flush();if(learningLayer)return;try{const cur=await api('/api/journeys/current');if(cur.journey&&cur.activity){currentActivity=cur.activity;await localDB.set('currentActivity',currentActivity)}}catch{}loadHome().catch(()=>{})});window.addEventListener('offline',()=>{if(learningLayer)return;if(currentActivity)showActivity();else loadHome().catch(()=>{})});
(async()=>{try{await localDB.flush();await loadHome()}catch(e){const c=await localDB.get('homeData:For You');if(c){homeData=c;shell(cardHTML(c.priority_card))}else shell(`<div class="card"><h1>Could not load</h1><div class="muted">${esc(e.message)}</div></div>`)}})();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js?v=16',{updateViaCache:'none'}).catch(()=>{});
